/**
 * Helpers for clients generated by `distributed game-client` from a Rust
 * game surface: typed event codecs and subscriptions, typed reads of
 * replicated entity fields, and correction-default merging.
 */
import type { GameClient } from './client.js';
import type { EventMessage } from './messages.js';
import type { CorrectionPolicies } from './prediction.js';
import type { EntityFields } from './replica.js';

/** One event type: stable id, name and payload codec. */
export type GameEventCodec<T> = Readonly<{
	id: number;
	name: string;
	encode(value: T): Uint8Array;
	decode(payload: Uint8Array): T;
}>;

/** Codecs of a surface's events, keyed by event name. */
export type GameEventCodecs<M> = { readonly [K in keyof M]: GameEventCodec<M[K]> };

/** A decoded event: `{ name, value }` discriminated by name. */
export type DecodedGameEvent<M> = { [K in keyof M]: Readonly<{ name: K; value: M[K] }> }[keyof M];

/** Anything that emits `('event', zoneId, EventMessage)` (a `GameClient`). */
export type GameEventSource = Pick<GameClient<never>, 'on'>;

/** Decode an Event message; `undefined` for type ids not in `codecs`. */
export function decodeGameEvent<M>(
	codecs: GameEventCodecs<M>,
	event: Pick<EventMessage, 'typeId' | 'payload'>
): DecodedGameEvent<M> | undefined {
	for (const name of Object.keys(codecs) as (keyof M)[]) {
		const codec = codecs[name];
		if (codec.id === event.typeId) {
			return { name, value: codec.decode(event.payload) } as DecodedGameEvent<M>;
		}
	}
	return undefined;
}

/** Subscribe to one typed event of every zone of `client`; returns the unsubscribe. */
export function onGameEvent<M, K extends keyof M>(
	client: GameEventSource,
	codecs: GameEventCodecs<M>,
	name: K,
	handler: (value: M[K], zoneId: string) => void
): () => void {
	const codec = codecs[name];
	return (client as Pick<GameClient<unknown>, 'on'>).on('event', (zoneId, event) => {
		if (event.typeId !== codec.id) return;
		handler(codec.decode(event.payload), zoneId);
	});
}

/** A replicated number field (0 when missing or not numeric). */
export function fieldNumber(fields: EntityFields, name: string): number {
	const v = fields[name];
	return typeof v === 'number' ? v : typeof v === 'boolean' ? (v ? 1 : 0) : 0;
}

/** A replicated `bool` field. */
export function fieldBool(fields: EntityFields, name: string): boolean {
	const v = fields[name];
	return v === true || (typeof v === 'number' && v !== 0);
}

/** A replicated `short_str` field. */
export function fieldString(fields: EntityFields, name: string): string {
	const v = fields[name];
	return typeof v === 'string' ? v : '';
}

/** A replicated `bytes` field. */
export function fieldBytes(fields: EntityFields, name: string): Uint8Array {
	const v = fields[name];
	return v instanceof Uint8Array ? v : new Uint8Array(0);
}

/** `defaults` with `overrides` applied per kind and field. */
export function mergeCorrections(
	defaults: CorrectionPolicies,
	overrides: CorrectionPolicies | undefined
): CorrectionPolicies {
	if (overrides === undefined) return defaults;
	const out: Record<string, Record<string, CorrectionPolicies[string][string]>> = {};
	for (const [kind, fields] of Object.entries(defaults)) out[kind] = { ...fields };
	for (const [kind, fields] of Object.entries(overrides)) out[kind] = { ...out[kind], ...fields };
	return out;
}
